/// Renders the `refactor` command's result -- the AI-assisted, whole-file
/// rewrites it applied (or would apply) -- as human-readable reports.
///
/// Like the pipeline reporters, both generators are data-driven from a plain
/// JSON map, keeping this package decoupled from the CLI's types. The expected
/// shape (produced by the `refactor` command):
///
/// ```json
/// {
///   "project": "...", "generatedAt": "...",
///   "applied": true, "minConfidence": 0.7,
///   "checkpoint": { "strategy": "stash", "ref": "abc123" },
///   "totals": { "refactored": 12, "failed": 0, "skipped": 2,
///               "linesAdded": 984, "linesRemoved": 1003 },
///   "files": [ { "file": "lib/x.dart", "ruleId": "refactor",
///                "confidence": 0.82, "linesAdded": 40, "linesRemoved": 55,
///                "diff": "..." } ],
///   "failed":  [ { "file": "lib/y.dart", "reason": "..." } ],
///   "skipped": [ "lib/z.dart (skipped: ...)" ]
/// }
/// ```
library;

/// Generates a single, self-contained HTML report from the refactor JSON.
///
/// Everything (CSS included) is inlined; the file opens from disk with no
/// server or network access.
String generateRefactorHtmlReport(Map<String, dynamic> report) {
  final totals = (report['totals'] as Map?)?.cast<String, dynamic>() ?? {};
  final files = (report['files'] as List?) ?? const [];
  final failed = (report['failed'] as List?) ?? const [];
  final skipped = (report['skipped'] as List?) ?? const [];
  final applied = report['applied'] == true;
  final checkpoint = (report['checkpoint'] as Map?)?.cast<String, dynamic>();

  final b = StringBuffer()
    ..writeln('<!doctype html>')
    ..writeln('<html lang="en"><head>')
    ..writeln('<meta charset="utf-8">')
    ..writeln('<meta name="viewport" content="width=device-width, initial-scale=1">')
    ..writeln('<title>CodeGuardian Refactor Report</title>')
    ..writeln('<style>$_css</style>')
    ..writeln('</head><body>')
    ..writeln('<header class="hero">')
    ..writeln('<div>')
    ..writeln('<h1>CodeGuardian Refactor Report</h1>')
    ..writeln(
      '<p class="meta">${_esc('${report['project'] ?? ''}')} &middot; '
      'AI-assisted refactor &middot; '
      '${_esc('${report['generatedAt'] ?? ''}')}</p>',
    )
    ..writeln('<div class="badges">')
    ..writeln(_badge(applied ? 'Refactors applied' : 'Dry run (preview)',
        applied ? 'ok' : 'warn'))
    ..writeln(_badge(
        'min confidence ${_num(report['minConfidence'])}', 'info'))
    ..writeln('</div>')
    ..writeln('</div></header>');

  b
    ..writeln('<section class="totals">')
    ..write(_stat(applied ? 'Files refactored' : 'Files to refactor',
        '${totals['refactored'] ?? files.length}'))
    ..write(_stat('Lines added', '+${totals['linesAdded'] ?? 0}', color: '#16a34a'))
    ..write(_stat('Lines removed', '-${totals['linesRemoved'] ?? 0}', color: '#dc2626'))
    ..write(_stat('Skipped', '${totals['skipped'] ?? skipped.length}'))
    ..write(_stat('Failed', '${totals['failed'] ?? failed.length}'))
    ..writeln('</section>')
    ..writeln('<main>');

  if (checkpoint != null && applied) {
    b.writeln('<p class="note">A git checkpoint '
        '(<code>${_esc('${checkpoint['strategy'] ?? ''}')}</code> '
        '<code>${_esc('${checkpoint['ref'] ?? ''}')}</code>) was created before '
        'applying &mdash; revert with git if needed.</p>');
  }

  b.write(_scoringExplainer(report));

  if (files.isEmpty) {
    b.writeln('<p class="clean">No files were refactored.</p>');
  }
  for (final raw in files) {
    final f = (raw as Map).cast<String, dynamic>();
    b.write(_fileSection(f, applied: applied));
  }

  if (failed.isNotEmpty) {
    b.writeln('<section class="panel"><h3>Failed to apply '
        '(${failed.length})</h3><ul class="failed">');
    for (final raw in failed) {
      final f = (raw as Map).cast<String, dynamic>();
      b.writeln('<li><code>${_esc('${f['file'] ?? ''}')}</code>: '
          '${_esc('${f['reason'] ?? ''}')}</li>');
    }
    b.writeln('</ul></section>');
  }

  if (skipped.isNotEmpty) {
    b.writeln('<section class="panel"><h3>Skipped '
        '(${skipped.length})</h3><ul class="skipped">');
    for (final note in skipped) {
      b.writeln('<li>${_esc('$note')}</li>');
    }
    b.writeln('</ul></section>');
  }

  b
    ..writeln('</main>')
    ..writeln('<footer>Generated by CodeGuardian AI</footer>')
    ..writeln('</body></html>');

  return b.toString();
}

String _fileSection(Map<String, dynamic> f, {required bool applied}) {
  final conf = (f['confidence'] as num?)?.toDouble() ?? 0.0;
  final added = f['linesAdded'] ?? 0;
  final removed = f['linesRemoved'] ?? 0;
  final s = StringBuffer()
    ..writeln('<section class="file">')
    ..writeln('<h2><code>${_esc('${f['file'] ?? ''}')}</code>'
        '<span class="chip ${_confClass(conf)}">confidence '
        '${conf.toStringAsFixed(2)}</span>'
        '<span class="chip add">+$added</span>'
        '<span class="chip del">-$removed</span></h2>')
    ..writeln('<details><summary>View diff</summary>'
        '<pre class="diff">${_diffHtml('${f['diff'] ?? ''}')}</pre></details>')
    ..writeln('</section>');
  return s.toString();
}

/// Generates a compact Markdown version of the same report (for PR comments
/// or a terminal-friendly summary).
String generateRefactorMarkdownReport(Map<String, dynamic> report) {
  final totals = (report['totals'] as Map?)?.cast<String, dynamic>() ?? {};
  final files = (report['files'] as List?) ?? const [];
  final failed = (report['failed'] as List?) ?? const [];
  final skipped = (report['skipped'] as List?) ?? const [];
  final applied = report['applied'] == true;

  final b = StringBuffer()
    ..writeln('# CodeGuardian Refactor Report')
    ..writeln()
    ..writeln('- **Project:** ${report['project'] ?? ''}')
    ..writeln('- **Run:** ${applied ? 'refactors applied' : 'dry run (preview)'}')
    ..writeln('- **Min confidence:** ${_num(report['minConfidence'])}')
    ..writeln('- **Files ${applied ? 'refactored' : 'to refactor'}:** '
        '${totals['refactored'] ?? files.length} '
        '(+${totals['linesAdded'] ?? 0} / -${totals['linesRemoved'] ?? 0} lines)')
    ..writeln('- **Skipped:** ${totals['skipped'] ?? skipped.length} · '
        '**Failed:** ${totals['failed'] ?? failed.length}')
    ..writeln();

  b
    ..writeln('<details><summary>How to read this report — what the numbers '
        'mean</summary>')
    ..writeln()
    ..writeln('**Confidence** (the number on every file, `0.00`–`1.00`) is how '
        'sure the AI is that its rewrite is correct and keeps the code '
        'behaving exactly as before — the AI grading its own work. Higher is '
        'safer.')
    ..writeln()
    ..writeln('- `0.85`–`1.00` — very confident, safe to accept.')
    ..writeln('- `0.70`–`0.85` — confident enough to apply, but worth a quick '
        'review.')
    ..writeln('- below `0.70` — not trusted, so it is skipped rather than '
        'applied.')
    ..writeln()
    ..writeln('The **min confidence** cut-off (`${_num(report['minConfidence'])}`) '
        'is the threshold: anything below it is thrown away, so a shaky change '
        'never touches your code. **+/-** counts the lines each rewrite adds '
        'and removes.')
    ..writeln()
    ..writeln('</details>')
    ..writeln();

  if (files.isNotEmpty) {
    b
      ..writeln('| File | Confidence | +/- |')
      ..writeln('|---|---:|---:|');
    for (final raw in files) {
      final f = (raw as Map).cast<String, dynamic>();
      final conf = (f['confidence'] as num?)?.toDouble() ?? 0.0;
      b.writeln('| `${f['file']}` | ${conf.toStringAsFixed(2)} | '
          '+${f['linesAdded'] ?? 0} / -${f['linesRemoved'] ?? 0} |');
    }
    b.writeln();
  }

  if (skipped.isNotEmpty) {
    b.writeln('<details><summary>Skipped (${skipped.length})</summary>\n');
    for (final note in skipped) {
      b.writeln('- $note');
    }
    b.writeln('\n</details>');
  }

  return b.toString();
}

/// A plain-language "how to read this report" panel, so a non-expert reader
/// understands what the confidence number means and how the tool decides which
/// rewrites to apply. Kept collapsed by default so it never crowds the results.
String _scoringExplainer(Map<String, dynamic> report) {
  final min = _num(report['minConfidence']);
  return '<details class="explainer"><summary>How to read this report '
      '&mdash; what the numbers mean</summary>'
      '<div class="explainer-body">'
      '<h3>Confidence &mdash; the number on every file</h3>'
      '<p>Each file below shows a <strong>confidence</strong> score from '
      '<code>0.00</code> to <code>1.00</code>. It is how sure the AI is that '
      'its rewrite of that file is correct and keeps the code behaving exactly '
      'as before &mdash; think of it as the AI grading its own work, where '
      '<code>1.00</code> means "completely sure" and <code>0.00</code> means '
      '"not sure at all". A higher number is a safer, more trustworthy '
      'change.</p>'
      '<p>The colour tells you the trust level at a glance:</p>'
      '<ul class="legend">'
      '<li><span class="chip ok">0.85 &ndash; 1.00</span> very confident '
      '&mdash; safe to accept.</li>'
      '<li><span class="chip warn">0.70 &ndash; 0.85</span> confident enough '
      'to apply, but worth a quick review.</li>'
      '<li><span class="chip bad">below 0.70</span> not trusted &mdash; '
      'skipped, not applied.</li>'
      '</ul>'
      '<h3>The cut-off (min confidence: <code>$min</code>)</h3>'
      '<p>Any rewrite scoring below this threshold is thrown away rather than '
      'applied, so a shaky change never touches your code. That is why some '
      'files can appear under <em>Skipped</em> &mdash; the AI was not sure '
      'enough about them.</p>'
      '<h3>Lines added / removed</h3>'
      '<p>The <span class="chip add">+</span> and <span class="chip del">-'
      '</span> chips show how many lines the rewrite adds and removes. Open '
      '<em>View diff</em> on any file to see the exact before-and-after '
      'changes (green = added, red = removed).</p>'
      '</div></details>';
}

String _stat(String label, String value, {String? color}) =>
    '<div class="stat"><span class="n"'
    '${color != null ? ' style="color:$color"' : ''}>${_esc(value)}</span>'
    '<span class="l">${_esc(label)}</span></div>';

String _badge(String text, String kind) =>
    '<span class="badge $kind">${_esc(text)}</span>';

String _confClass(double c) =>
    c >= 0.85 ? 'ok' : (c >= 0.7 ? 'warn' : 'bad');

String _num(Object? n) =>
    n is num ? n.toStringAsFixed(2) : '${n ?? ''}';

String _diffHtml(String diff) {
  final out = StringBuffer();
  for (final line in diff.split('\n')) {
    final cls = line.startsWith('+') && !line.startsWith('+++')
        ? 'add'
        : line.startsWith('-') && !line.startsWith('---')
            ? 'del'
            : line.startsWith('@@')
                ? 'hunk'
                : '';
    out.writeln('<span class="$cls">${_esc(line)}</span>');
  }
  return out.toString();
}

String _esc(String text) => text
    .replaceAll('&', '&amp;')
    .replaceAll('<', '&lt;')
    .replaceAll('>', '&gt;')
    .replaceAll('"', '&quot;');

